"use client";
import React from "react";
import { 
  ShieldCheck, 
  Camera, 
  Truck, 
  RefreshCcw, 
  Scale, 
  AlertTriangle, 
  Lock,
  FileText,
  BadgeAlert
} from "lucide-react";

const termsData = [
  {
    id: "01",
    title: "The Unboxing Mandate",
    desc: "Strict verification protocol for all physical assets.",
    content: "To qualify for any return or replacement, the User must record a continuous 360° unboxing video. The footage must begin with the sealed courier bag (showing the label) and continue through the full inspection without any cuts, edits, or transitions. No video = No claim.",
    icon: <Camera size={20} className="text-brand" />
  },
  {
    id: "02",
    title: "COD Security Protocol",
    desc: "Commitment deposit for Cash-on-Delivery.",
    content: "All COD orders require a ₹200 non-refundable security deposit. This fee covers courier management and risk mitigation. This amount is NOT deductible from the product value and is not refundable under any circumstances, including delivery refusal.",
    icon: <BadgeAlert size={20} className="text-brand" />
  },
  {
    id: "03",
    title: "Inspection Window",
    desc: "Time-locked reporting for defects.",
    content: "Any discrepancies, damages, or manufacturing defects must be reported within 24 hours of the delivery timestamp. Reports made after this 24-hour window will be deemed invalid as the product is considered 'User Accepted'.",
    icon: <ShieldCheck size={20} className="text-brand" />
  },
  {
    id: "04",
    title: "Logistical Liability",
    desc: "Responsibility for reverse transit.",
    content: "If we dispatch the wrong size or product, we bear 100% of the replacement costs. If the user selects the wrong size, the user must manage and pay for all shipping and processing expenses for the exchange.",
    icon: <Truck size={20} className="text-brand" />
  }
];

export default function TermsOfServicePage() {
  return (
    <div className="bg-[#050505] text-[#f0f0f0] min-h-screen pb-32 selection:bg-brand selection:text-black font-sans">
      
      {/* 1. LEGAL HEADER */}
      <header className="pt-24 pb-20 px-6 max-w-7xl mx-auto border-b border-white/5">
        <div className="flex items-center gap-2 mb-6 px-4 py-1.5 rounded-full bg-brand/10 border border-brand/20 w-fit">
          <Scale size={12} className="text-brand" />
          <span className="text-[9px] font-black uppercase tracking-[0.5em] text-brand">Legal Framework v2.0.26</span>
        </div>
        <h1 className="text-7xl md:text-[8vw] font-black uppercase italic tracking-tighter leading-[0.8] mb-10">
          Terms of <br /> <span className="opacity-10 italic">Service.</span>
        </h1>
        <p className="max-w-2xl text-[11px] font-bold uppercase leading-relaxed opacity-40 tracking-widest italic">
          This document governs the interaction between the Architect and the User. By accessing this platform, you agree to the protocols defined below.
        </p>
      </header>

      {/* 2. CORE TERMS BENTO GRID */}
      <main className="max-w-7xl mx-auto px-6 mt-16 grid grid-cols-1 md:grid-cols-2 gap-6">
        {termsData.map((item) => (
          <div key={item.id} className="group bg-[#0a0a0a] border border-white/5 rounded-[3rem] p-10 hover:border-brand/30 transition-all duration-500">
            <div className="flex flex-col h-full justify-between gap-8">
              <div className="space-y-6">
                <div className="flex items-center justify-between">
                  <div className="p-4 bg-white/5 rounded-2xl group-hover:bg-brand/10 transition-colors">
                    {item.icon}
                  </div>
                  <span className="text-xs font-black opacity-10 italic tracking-tighter">SECTION_{item.id}</span>
                </div>
                <div className="space-y-2">
                  <h3 className="text-2xl font-black uppercase italic tracking-tighter">{item.title}</h3>
                  <p className="text-[10px] font-black uppercase tracking-widest text-brand">{item.desc}</p>
                </div>
                <p className="text-[12px] font-medium opacity-50 leading-relaxed uppercase italic">
                  {item.content}
                </p>
              </div>
            </div>
          </div>
        ))}
      </main>

      {/* 3. ADDITIONAL LEGAL ARTICLES */}
      <section className="max-w-7xl mx-auto px-6 mt-6">
        <div className="bg-white/5 rounded-[4rem] p-12 md:p-20 border border-white/5">
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-16">
            <div className="space-y-8">
              <h2 className="text-5xl font-black uppercase italic tracking-tighter leading-none">
                Extended <br /> Provisions.
              </h2>
              <div className="space-y-6">
                <div className="flex gap-4 items-start">
                  <Lock className="text-brand shrink-0" size={18} />
                  <div>
                    <h4 className="text-xs font-black uppercase tracking-widest mb-2">Intellectual Property</h4>
                    <p className="text-[10px] opacity-40 font-bold uppercase leading-tight">All UI logic, Fit Architect code, and proprietary photography are protected under international IP laws.</p>
                  </div>
                </div>
                <div className="flex gap-4 items-start">
                  <RefreshCcw className="text-brand shrink-0" size={18} />
                  <div>
                    <h4 className="text-xs font-black uppercase tracking-widest mb-2">Modification Rights</h4>
                    <p className="text-[10px] opacity-40 font-bold uppercase leading-tight">We reserve the right to update these terms without prior notification to reflect market and logistical changes.</p>
                  </div>
                </div>
              </div>
            </div>

            {/* CRITICAL WARNING CARD */}
            <div className="bg-brand p-10 rounded-[3rem] text-black flex flex-col justify-center gap-6 group">
              <div className="flex items-center gap-3">
                <AlertTriangle size={24} className="animate-pulse" />
                <h3 className="text-2xl font-black uppercase italic tracking-tighter">Fraud Protection</h3>
              </div>
              <p className="text-xs font-bold uppercase leading-relaxed italic">
                Any attempt to return low-tier replicas in place of OG/Surplus stock will result in a permanent system ban and legal escalation. Every high-tier pair sent is digitally fingerprinted for verification.
              </p>
            </div>
          </div>
        </div>
      </section>

      {/* 4. FINAL ACCEPTANCE FOOTER */}
      <footer className="mt-24 px-6 max-w-7xl mx-auto text-center">
        <div className="flex flex-col items-center gap-8 py-12 border-t border-white/5">
           <FileText size={32} className="opacity-20" />
           <p className="max-w-md text-[10px] font-black uppercase tracking-[0.3em] opacity-30 leading-loose">
             By placing an order on this platform, you acknowledge that you have read, understood, and agreed to the Unboxing Mandate and COD Security Protocols.
           </p>
           <div className="flex gap-6 text-[8px] font-black uppercase tracking-widest opacity-20">
             <span>Architect © 2026</span>
             <span>All Protocols Active</span>
           </div>
        </div>
      </footer>
    </div>
  );
}